<?php
$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/StoryMediaService.php';AuthService::boot();$writer=AuthService::requireWriter();$error=null;$notice=null;
$plotId=(int)($_GET['plot']??$_POST['plot_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');if($action==='upload'){StoryMediaService::upload($writer,$plotId,$_POST,$_FILES['image']??[]);$notice='The image is now available to this story.';}if($action==='deactivate'){StoryMediaService::deactivate($writer,(int)$_POST['media_asset_id']);$notice='The image was removed from player view.';}}catch(Throwable $e){$error=$e->getMessage();}}
if((int)$writer['is_admin']===1)$q=db()->query('SELECT p.*,u.display_name author_name,u.email author_email FROM plots p LEFT JOIN users u ON u.user_id=p.author_user_id ORDER BY p.title');
else{$q=db()->prepare('SELECT p.*,u.display_name author_name,u.email author_email FROM plots p LEFT JOIN users u ON u.user_id=p.author_user_id WHERE p.author_user_id=? ORDER BY p.title');$q->execute([$writer['user_id']]);}
$plots=$q->fetchAll();if($plotId<1&&$plots)$plotId=(int)$plots[0]['plot_id'];$plot=null;foreach($plots as$p)if((int)$p['plot_id']===$plotId)$plot=$p;if($plotId&&(!$plot||!StoryMediaService::canEdit($writer,$plotId))){http_response_code(403);exit('You may not edit that story.');}
$roles=$events=$assets=[];if($plot){$q=db()->prepare('SELECT role_code,name,pronoun_set FROM plot_roles WHERE plot_id=? ORDER BY slot_no');$q->execute([$plotId]);$roles=$q->fetchAll();$q=db()->prepare('SELECT event_code,headline,trigger_second FROM plot_events WHERE plot_id=? ORDER BY trigger_second,event_id');$q->execute([$plotId]);$events=$q->fetchAll();$assets=StoryMediaService::forPlot($plotId);}
function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Story Writer · Toinky</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#202335;background:#f4f1ea}*{box-sizing:border-box}body{margin:0}.bar{background:#171a2b;color:#fff;padding:16px}.barin,.shell{max-width:1120px;margin:auto}.barin{display:flex;justify-content:space-between;gap:16px}.bar a{color:#fff}.shell{padding:24px 16px}.grid{display:grid;grid-template-columns:260px 1fr;gap:20px}.card{background:#fff;border:1px solid #d9d4ca;border-radius:14px;padding:20px;margin-bottom:18px}.story-link{display:block;padding:10px;border-radius:8px;color:#3d345f;text-decoration:none}.story-link.active{background:#eee9ff;font-weight:800}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.field{display:block;font-weight:700}.field input,.field select,.field textarea{display:block;width:100%;margin-top:5px;padding:10px;border:1px solid #c9c3b9;border-radius:8px;font:inherit}.wide{grid-column:1/-1}.btn{border:0;border-radius:8px;background:#5947a0;color:#fff;padding:10px 14px;font-weight:800;cursor:pointer}.btn.alt{background:#fff;color:#5947a0;border:1px solid #5947a0}.asset{display:grid;grid-template-columns:150px 1fr auto;gap:15px;align-items:start;border-top:1px solid #e4dfd7;padding:15px 0}.asset img{width:150px;max-height:100px;object-fit:cover;border-radius:8px}.muted{color:#6b6c78}.notice,.error{padding:12px;border-radius:9px}.notice{background:#dcfce7}.error{background:#fee2e2;color:#991b1b}@media(max-width:760px){.grid,.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}.asset{grid-template-columns:90px 1fr}.asset img{width:90px}.asset form{grid-column:2}}
</style></head><body><header class="bar"><div class="barin"><b>Toinky Story Writer</b><nav><a href="./">Player Portal</a><?php if((int)$writer['is_admin']===1):?> · <a href="admin.php">Admin</a><?php endif;?></nav></div></header><main class="shell"><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><?php if($notice):?><p class="notice"><?=e($notice)?></p><?php endif;?><div class="grid"><aside class="card"><h2>Your Stories</h2><?php if(!$plots):?><p class="muted">No stories are assigned to you yet.</p><?php endif;?><?php foreach($plots as$p):?><a class="story-link <?=((int)$p['plot_id']===$plotId)?'active':''?>" href="?plot=<?=(int)$p['plot_id']?>"><?=e($p['title'])?><br><small><?=e($p['author_name']??'Unassigned')?></small></a><?php endforeach;?></aside><div><?php if($plot):?><section class="card"><small>Story Artwork</small><h1><?=e($plot['title'])?></h1><p>Author: <?=e($plot['author_name']??'Unassigned')?><?=!empty($plot['author_email'])?' · '.e($plot['author_email']):''?></p><p class="muted">Artwork is optional. The story remains playable when some or all images are missing. Only uploaded, active images are shown.</p></section><section class="card"><h2>Add an Image</h2><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="upload"><input type="hidden" name="plot_id" value="<?=$plotId?>"><label class="field">Image placement<select name="placement" required><?php foreach(['CHARACTER'=>'Character','OPENING'=>'Opening Scene','SCENE'=>'Story Scene','TURNING_POINT'=>'Important Turning Point','OUTCOME'=>'Specific Outcome','ENDING'=>'Ending / Closing','OTHER'=>'Other']as$k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach;?></select></label><label class="field">Asset code<input name="asset_code" placeholder="e.g. STORM_BREAKS_WINDOW"></label><label class="field">Character (optional)<select name="role_code"><option value="">Any character</option><?php foreach($roles as$r):?><option value="<?=e($r['role_code'])?>"><?=e($r['name'])?> · <?=e($r['pronoun_set'])?></option><?php endforeach;?></select></label><label class="field">Story event (optional)<select name="event_code"><option value="">No event binding</option><?php foreach($events as$ev):?><option value="<?=e($ev['event_code'])?>"><?=e($ev['event_code'].' · '.$ev['headline'])?></option><?php endforeach;?></select></label><label class="field">Story second (optional)<input type="number" min="0" name="scene_second"></label><label class="field">Outcome state key (optional)<input name="condition_state_key" placeholder="e.g. GUEST_STATUS"></label><label class="field">Condition<select name="condition_operator"><option value="">None</option><?php foreach(['EQ','NEQ','IN','NOT_IN','EXISTS','NOT_EXISTS']as$op):?><option><?=$op?></option><?php endforeach;?></select></label><label class="field">Condition value<input name="condition_value" placeholder="e.g. EVACUATED"></label><label class="field wide">Image<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><label class="field wide">Alternative text<input name="alt_text" maxlength="500" required placeholder="Describe what the image communicates"></label><label class="field">Title<input name="title_text"></label><label class="field">Display order<input type="number" name="sort_order" value="100"></label><label class="field wide">Caption<textarea name="caption_text" rows="3"></textarea></label><div class="wide"><button class="btn">Upload Image</button></div></form></section><section class="card"><h2>Uploaded Images</h2><?php if(!$assets):?><p class="muted">No artwork has been uploaded. This does not prevent the story from being played or submitted.</p><?php endif;?><?php foreach($assets as$a):?><article class="asset"><img src="<?=e($a['file_path'])?>" alt="<?=e($a['alt_text'])?>"><div><b><?=e($a['title_text']?:$a['asset_code'])?></b><br><span class="muted"><?=e(ucwords(strtolower(str_replace('_',' ',$a['placement']))))?><?=!empty($a['role_code'])?' · '.e($a['role_code']):''?><?=!empty($a['event_code'])?' · '.e($a['event_code']):''?><?=!empty($a['condition_state_key'])?' · '.e($a['condition_state_key'].' '.$a['condition_operator'].' '.$a['condition_value']):''?><br><?=e($a['alt_text'])?> · <?=((int)$a['active']===1)?'Active':'Hidden'?></span></div><?php if((int)$a['active']===1):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="deactivate"><input type="hidden" name="plot_id" value="<?=$plotId?>"><input type="hidden" name="media_asset_id" value="<?=(int)$a['media_asset_id']?>"><button class="btn alt">Hide</button></form><?php endif;?></article><?php endforeach;?></section><?php endif;?></div></div></main></body></html>